/* ioi_core.h — the boundary between code generated by `ick` and the core
 * runtime (runtime/core/). Owned by the compiler.
 *
 * Generated programs keep their variables in static arrays and call these
 * helpers; everything that would otherwise be repeated per statement lives
 * here. Behaviour mirrors C-INTERCAL 0.35's libick (cesspool.c, fiddle.c,
 * ick_lose.c) byte for byte where INTERCAL-72 is concerned.
 */
#ifndef IOI_CORE_H
#define IOI_CORE_H

#include <stddef.h>
#include <stdint.h>

#include "ioi_cassette.h"

/* An INTERCAL array (tail `,` holds uint16_t, hybrid `;` holds uint32_t).
 * rank 0 means "never dimensioned". */
typedef struct ioi_array {
    uint32_t rank;
    uint32_t *dims;
    void *data;
} ioi_array;

/* Variable kinds, as used by STASH/RETRIEVE. */
enum { IOI_ONESPOT = 1, IOI_TWOSPOT = 2, IOI_TAIL = 3, IOI_HYBRID = 4 };

/* Line number reported by runtime errors ("ON THE WAY TO n"). Generated
 * code sets it at the start of every statement. */
extern int ioi_lineno;

/* ---- start-up and errors ------------------------------------------------ */

void ioi_init(int argc, char **argv);

/* Print the C-INTERCAL error message for CODE (ICLnnnI ...), run the error
 * hook (Interstates: error page), and exit with status CODE. ARG fills the
 * %s of E000 and E579 (and carries detail for Interstates errors). */
_Noreturn void ioi_lose(int code, int line, const char *arg);

/* Format the message ioi_lose would print (without exiting). */
const char *ioi_error_message(int code, int line, const char *arg);

/* Called by ioi_lose with the formatted message before exiting. */
void ioi_set_error_hook(void (*hook)(int code, const char *message));

/* Flush, run the exit hook (Interstates: send the response) and exit(0). */
_Noreturn void ioi_give_up(void);
void ioi_set_exit_hook(void (*hook)(void));

/* ---- operators ---------------------------------------------------------- */

uint32_t ioi_mingle(uint32_t r, uint32_t s);
uint32_t ioi_select(uint32_t r, uint32_t s);
uint32_t ioi_and16(uint32_t n);
uint32_t ioi_or16(uint32_t n);
uint32_t ioi_xor16(uint32_t n);
uint32_t ioi_and32(uint32_t n);
uint32_t ioi_or32(uint32_t n);
uint32_t ioi_xor32(uint32_t n);

/* ---- storage ------------------------------------------------------------ */

/* Assignment with IGNORE (ign != 0: value checked but not stored). */
void ioi_set16(uint16_t *p, int ign, uint32_t v);
void ioi_set32(uint32_t *p, int ign, uint32_t v);

/* Element address; N subscripts in SUBS. E241 on rank/range mismatch. */
uint16_t *ioi_aref16(ioi_array *a, int n, const uint32_t *subs);
uint32_t *ioi_aref32(ioi_array *a, int n, const uint32_t *subs);

/* Dimension (array <- dim BY dim ...). wide: hybrid. */
void ioi_resize(ioi_array *a, int wide, int ign, int n, const uint32_t *dims);

void ioi_stash(int type, int idx, void *var);
void ioi_retrieve(int type, int idx, void *var, int ign);

/* ---- control ------------------------------------------------------------ */

void ioi_next_push(int ret);
int ioi_resume(uint32_t n);
void ioi_forget(uint32_t n);
int ioi_roll(int percent);

/* ---- I/O ---------------------------------------------------------------- */

void ioi_read_out(uint32_t v);
void ioi_read_out_array(ioi_array *a, int wide);
uint32_t ioi_write_in(void);
void ioi_write_in_array(ioi_array *a, int wide, int ign);

/* Butchered Roman numerals: the two lines READ OUT prints, without the
 * final newline. BUF needs 96 bytes. */
void ioi_roman(uint32_t v, char *buf);

/* ======================================================================== */
/* Interstates (-s) values. A value is a uint32_t per ioi_cassette.h.       */
/* ======================================================================== */

/* Value -> number for arithmetic and scalar assignment: BYTES are parsed
 * as decimal (E410 otherwise), LIST is E411. */
uint32_t ioi_num(uint32_t v);
/* Number -> value for a hybrid element. */
#define ioi_box(n) ioi_val_number(n)
/* LIST value SUB k (1-based); E241 when out of range, E411 if not a LIST
 * (a whole-array value is accepted too, see ioi_hyb_list). */
uint32_t ioi_val_sub(uint32_t v, uint32_t k);

/* Whole arrays as values. Never-dimensioned tail -> empty BYTES. */
uint32_t ioi_tail_value(const ioi_array *a);
uint32_t ioi_hyb_value(const ioi_array *a);

/* Whole-array assignment with the implicit conversions of SPEC.md §2.2. */
void ioi_tail_assign(ioi_array *a, int ign, uint32_t v);
void ioi_hyb_assign(ioi_array *a, int ign, uint32_t v);
/* ,n SUB k <- value (numbers only). */
void ioi_tail_elem_assign(uint16_t *p, int ign, uint32_t v);
/* Fill a tail array with bytes (dimension = len, 0 allowed). */
void ioi_tail_set_bytes(ioi_array *a, int ign, const void *data, size_t len);

/* STASH-assign: element address of a one-dimensional array, extending it
 * (new elements 0) when K exceeds the dimension. */
uint16_t *ioi_aref16_grow(ioi_array *a, uint32_t k);
uint32_t *ioi_aref32_grow(ioi_array *a, uint32_t k);

/* ---- templates ---------------------------------------------------------- */

/* Filters of {{EXPR FILTER}}. IOI_F_PLAIN may be or-ed in: the tag sits in
 * an attribute value, comment or raw-text/RCDATA element (title, textarea,
 * script, style), so markup must not be emitted there. */
enum {
    IOI_F_DEFAULT = 0, IOI_F_ARABIC, IOI_F_ROMAN, IOI_F_RAW, IOI_F_PROSE,
    IOI_F_AGO, IOI_F_FACE,
    IOI_F_PLAIN = 0x100
};

/* Template variable context: the program's ,1..,144 / ;1..;144 / .144
 * (NULL entries are variables no code mentions). */
struct ioi_tpl_vars {
    ioi_array *const *tail;   /* [145] */
    ioi_array *const *hyb;    /* [145] */
    uint16_t *dot144;         /* may be NULL */
};

void ioi_tpl_text(const char *s, size_t n);
/* Render a value (number, BYTES, LIST) with FILTER. */
void ioi_tpl_value(uint32_t v, int filter);
/* Render a plain number (from a 16/32-bit expression) with FILTER. */
void ioi_tpl_number(uint32_t n, int filter);
/* Roman numerals as HTML (overbars as <span class="ick-bar">). */
void ioi_tpl_roman(uint32_t n);
/* Roman numerals as plain text (U+0305 COMBINING OVERLINE after each
 * barred letter): safe inside attributes and raw-text elements. */
void ioi_tpl_roman_plain(uint32_t n);

/* READ OUT #n WITH TEMPLATE: extract ;49221 SUB 1..n into ,144.. / ;144.. */
void ioi_tpl_extract(const struct ioi_tpl_vars *tv, ioi_array *params, uint32_t n);

/* Loops: begin saves the template variables, item extracts element I
 * (1-based) of the loop value, end restores. */
struct ioi_tpl_save;
struct ioi_tpl_save *ioi_tpl_save(const struct ioi_tpl_vars *tv);
void ioi_tpl_restore(const struct ioi_tpl_vars *tv, struct ioi_tpl_save *s);
/* Loop value -> LIST (whole hybrid arrays and LISTs; anything else E411). */
uint32_t ioi_tpl_loop_list(uint32_t v);
void ioi_tpl_item(const struct ioi_tpl_vars *tv, uint32_t elem, uint32_t index);

/* ---- web glue (only linked into -s programs) ---------------------------- */

/* Initialise the web runtime and install error/exit hooks that render the
 * error page / send the buffered response. */
void ioi_s_init(void);
/* Route dispatch failure (E404, "ON THE WAY TO 16000") / origin failure
 * (E403, "ON THE WAY TO" the route's origin label): error page, exit. */
_Noreturn void ioi_s_no_route(void);
_Noreturn void ioi_s_forbidden(int origin);
/* URL security for the matched route whose COME FROM names ORIGIN
 * (SPEC.md §2.4). */
void ioi_s_check_origin(int origin);
/* DB status check: E420/E421 with ioi_db_errmsg() detail. */
void ioi_s_db_check(int status);
/* STASH ;n INTO DATABASE #t; *rowid (may be NULL) receives the row id. */
void ioi_s_db_insert(unsigned table, ioi_array *a, uint32_t *rowid);
/* READ OUT x WITH SESSION (E422 when serving and the session cannot be stored). */
void ioi_s_session_set(uint32_t n);
/* A LIST holding one value. */
uint32_t ioi_s_list1(uint32_t v);

#endif
